BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @batchId INT;
        DECLARE @existingTotal INT;

        -- Validate input
        IF @batchCode IS NULL OR LTRIM(RTRIM(@batchCode)) = ''
        BEGIN
            RAISERROR('Batch code is required', 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END

        -- Check if batch already exists
        SELECT @batchId = batch_id, @existingTotal = total_applications
        FROM dbo.batch
        WHERE batch_code = @batchCode;

        IF @batchId IS NULL
        BEGIN
            -- Insert new batch and capture id
            INSERT INTO dbo.batch (batch_code, batch_name, created_by, total_applications)
            VALUES (@batchCode, 'Batch ' + @batchCode, @emp_id, ISNULL(@len, 1));

            SET @batchId = SCOPE_IDENTITY();

        END
        ELSE
        BEGIN
            -- Batch exists: increment total_applications.
            -- You can change the increment logic if @len represents multiple applications
            -- For single application add 1, for batch add @len
            UPDATE dbo.batch
            SET total_applications = ISNULL(total_applications, 0) --ISNULL(@len, 1)
            WHERE batch_id = @batchId;
        END

        -- Update leave_application row: set application_status, batch and checkpoint
        UPDATE dbo.leave_application
        SET 
            application_status = @role,
            batch = @batchCode,
            [checkpoint] = ISNULL(@checkpoint, '')
        WHERE leave_app_id = @leaveAppId;

        COMMIT TRANSACTION;

        -- Return success with batch info
        SELECT 
            'Success' AS status,
            @batchCode AS batch_code,
            @batchId AS batch_id,
            (SELECT total_applications FROM dbo.batch WHERE batch_id = @batchId) AS total_applications;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;

        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        RAISERROR('Error adding application to batch: %s', 16, 1, @ErrorMessage);
    END CATCH
END

CREATE PROCEDURE [dbo].[AddApplicationToBatch]
    @leaveAppId INT,
    @batchCode VARCHAR(12),
    @role VARCHAR(10),
    @checkpoint INT,
    @emp_id VARCHAR(10),
    @len INT
AS

BEGIN
    DECLARE @serviceDate DATE = @dateOfProbationary;
    DECLARE @specificDate DATE = DATEFROMPARTS(@year, @month, 1);

    -- Calculate the time difference in days
    DECLARE @timeDifference INT = DATEDIFF(DAY, @serviceDate, @specificDate);

    -- Calculate years, months, and days
    SET @years = @timeDifference / 365;
    SET @months = (@timeDifference % 365) / 30;
    SET @days = (@timeDifference % 365) % 30;

    -- Initialize balances
    SET @balanceVl = 0;
    SET @balanceSl = 0;
    DECLARE @balanceFl INT = 0;
    SET @vlAddLeave = 0;
    SET @slAddLeave = 0;

    -- Determine balance based on employee status and years of service
    IF @employeeStatus = 'probational'
    BEGIN
        SET @balanceVl = 5;
        SET @balanceSl = 0;
    END
    ELSE IF @employeeStatus = 'mavie'
    BEGIN
        SET @balanceVl = 0;
        SET @balanceSl = 0;
    END
    -- Additional leave calculation
    ELSE IF @employeeStatus = 'permanent'
    BEGIN
        SET @vlAddLeave = @balanceVl / 12.0;
        SET @slAddLeave = @balanceSl / 12.0;

        IF @month = MONTH(@serviceDate)
        BEGIN
            SET @balanceVl = CASE
                WHEN @years + 1 BETWEEN 0 AND 5 THEN 15
                WHEN @years + 1 BETWEEN 6 AND 10 THEN 16
                WHEN @years + 1 BETWEEN 11 AND 15 THEN 17
                WHEN @years + 1 BETWEEN 16 AND 20 THEN 18
                WHEN @years + 1 BETWEEN 21 AND 25 THEN 19
                WHEN @years + 1 BETWEEN 26 AND 30 THEN 20
                ELSE 21
            END;

			 SET @balanceSl = CASE
                WHEN @years + 1 BETWEEN 0 AND 5 THEN 15
                WHEN @years + 1 BETWEEN 6 AND 10 THEN 16
                WHEN @years + 1 BETWEEN 11 AND 15 THEN 17
                WHEN @years + 1 BETWEEN 16 AND 20 THEN 18
                WHEN @years + 1 BETWEEN 21 AND 25 THEN 19
                WHEN @years + 1 BETWEEN 26 AND 30 THEN 20
                ELSE 21
            END;

            SET @vlAddLeave = @balanceVl / 12.0;
            SET @slAddLeave = @balanceSl / 12.0;
        END
    END
	ELSE 
    BEGIN
         SET @balanceVl = 0;
         SET @balanceSl = 0;
    END

    -- Truncate leave balances to 2 decimal places
    -- SET @vlAddLeave = FLOOR(@vlAddLeave * 100) / 100.0;
    -- SET @slAddLeave = FLOOR(@slAddLeave * 100) / 100.0;
END;

CREATE PROCEDURE [dbo].[CalculateServiceDetails]
    @dateOfProbationary DATE,
    @month INT,
    @year INT,
    @employeeStatus NVARCHAR(50),
    @balanceVl INT OUTPUT,
    @balanceSl INT OUTPUT,
    @vlAddLeave DECIMAL(10, 2) OUTPUT,
    @slAddLeave DECIMAL(10, 2) OUTPUT,
    @years INT OUTPUT,
    @months INT OUTPUT,
    @days INT OUTPUT
AS

BEGIN
    DECLARE @serviceDate DATE = @dateOfProbationary;
    DECLARE @specificDate DATE = DATEFROMPARTS(@year, @month, 1);
    DECLARE @CurrentYear INT = YEAR(GETDATE());

    -- Calculate the time difference in days
    DECLARE @timeDifference INT = DATEDIFF(DAY, @serviceDate, @specificDate);
    DECLARE @gainedPercentage NVARCHAR(50);

    -- Calculate years, months, and days
    SET @years = @timeDifference / 365;
    SET @months = (@timeDifference % 365) / 30;
    SET @days = (@timeDifference % 365) % 30;

    -- Initialize balances and gainedForceLeave
    SET @balanceVl = 0.00;
    SET @balanceSl = 0.00;
    SET @vlAddLeave = 0.00;
    SET @slAddLeave = 0.00;
    SET @gainedForceLeave = 0;
    SET @balanceEl = 0;

    -- Get gained percentage for the current month
    SELECT @gainedPercentage = [class]
    FROM leave_gained
    WHERE employee_id = @employee_id  
    AND year = @year
    AND month = @month;

    DECLARE @serviceAnniversaryMonth INT = MONTH(@serviceDate);

    -- Determine balance based on employee status
    IF LTRIM(RTRIM(@employeeStatus)) = 'probational'
    BEGIN
        SET @balanceVl = 0.00;
        SET @balanceSl = 0.00;
        SET @balanceEl = 0;
    END
    ELSE IF LTRIM(RTRIM(@employeeStatus)) = 'mavie' 
    BEGIN
        SET @balanceVl = 0.00;
        SET @balanceSl = 0.00;
        SET @balanceEl = 0;
    END
    ELSE IF LTRIM(RTRIM(@employeeStatus)) = 'unknown' 
    BEGIN
        SET @balanceVl = 0.00;
        SET @balanceSl = 0.00;
        SET @balanceEl = 0;
    END
    ELSE IF LTRIM(RTRIM(@employeeStatus)) = 'oic' 
    BEGIN
       -- Set force leave eligibility
        IF EXISTS (SELECT 1 FROM force_leave_eligibility WHERE emp_id = @employee_id AND YEAR(date) = @CurrentYear)
            SET @gainedForceLeave = 10;
        ELSE
            SET @gainedForceLeave = 0;

        -- Calculate base balances based on years of service
        IF @years BETWEEN 0 AND 5
        BEGIN
            SET @balanceVl = 15.00;
            SET @balanceSl = 15.00;
        END
        ELSE IF @years BETWEEN 6 AND 10
        BEGIN
            SET @balanceVl = 16.00;
            SET @balanceSl = 16.00;
        END
        ELSE IF @years BETWEEN 11 AND 15
        BEGIN
            SET @balanceVl = 17.00;
            SET @balanceSl = 17.00;
        END
        ELSE IF @years BETWEEN 16 AND 20
        BEGIN
            SET @balanceVl = 18.00;
            SET @balanceSl = 18.00;
        END
        ELSE IF @years BETWEEN 21 AND 25
        BEGIN
            SET @balanceVl = 19.00;
            SET @balanceSl = 19.00;
        END
        ELSE IF @years BETWEEN 26 AND 30
        BEGIN
            SET @balanceVl = 20.00;
            SET @balanceSl = 20.00;
        END
        ELSE IF @years >= 31
        BEGIN
            SET @balanceVl = 21.00;
            SET @balanceSl = 21.00;
        END

        -- Calculate additional leave based on gained percentage
        IF @gainedPercentage IS NULL OR @gainedPercentage = 'F'
        BEGIN
            SET @vlAddLeave = @balanceVl / 12.0;
            SET @slAddLeave = @balanceSl / 12.0;
        END
        ELSE IF @gainedPercentage = 'H'
        BEGIN
            SET @vlAddLeave = (@balanceVl / 12.0) * 0.5;
            SET @slAddLeave = (@balanceSl / 12.0) * 0.5;
        END
        ELSE
        BEGIN
            SET @vlAddLeave = 0;
            SET @slAddLeave = 0;
        END

        -- Prorate balances for employees who became permanent during the year
        IF YEAR(@datePermanent) = @year
        BEGIN
            DECLARE @remainingMonthss INT = 12 - MONTH(@datePermanent) + 1;
            SET @balanceVl = (@balanceVl / 12.0) * @remainingMonthss;
            SET @balanceSl = (@balanceSl / 12.0) * @remainingMonthss;
        END
    END
    ELSE IF LTRIM(RTRIM(@employeeStatus)) = 'permanent' 
    BEGIN
        -- Set force leave eligibility
        IF EXISTS (SELECT 1 FROM force_leave_eligibility WHERE emp_id = @employee_id AND YEAR(date) = @CurrentYear)
            SET @gainedForceLeave = 10;
        ELSE
            SET @gainedForceLeave = 0;

        -- Calculate base balances based on years of service
        IF @years BETWEEN 0 AND 5
        BEGIN
            SET @balanceVl = 15.00;
            SET @balanceSl = 15.00;
        END
        ELSE IF @years BETWEEN 6 AND 10
        BEGIN
            SET @balanceVl = 16.00;
            SET @balanceSl = 16.00;
        END
        ELSE IF @years BETWEEN 11 AND 15
        BEGIN
            SET @balanceVl = 17.00;
            SET @balanceSl = 17.00;
        END
        ELSE IF @years BETWEEN 16 AND 20
        BEGIN
            SET @balanceVl = 18.00;
            SET @balanceSl = 18.00;
        END
        ELSE IF @years BETWEEN 21 AND 25
        BEGIN
            SET @balanceVl = 19.00;
            SET @balanceSl = 19.00;
        END
        ELSE IF @years BETWEEN 26 AND 30
        BEGIN
            SET @balanceVl = 20.00;
            SET @balanceSl = 20.00;
        END
        ELSE IF @years >= 31
        BEGIN
            SET @balanceVl = 21.00;
            SET @balanceSl = 21.00;
        END

        -- Calculate additional leave based on gained percentage
        IF @gainedPercentage IS NULL OR @gainedPercentage = 'F'
        BEGIN
            SET @vlAddLeave = @balanceVl / 12.0;
            SET @slAddLeave = @balanceSl / 12.0;
        END
        ELSE IF @gainedPercentage = 'H'
        BEGIN
            SET @vlAddLeave = (@balanceVl / 12.0) * 0.5;
            SET @slAddLeave = (@balanceSl / 12.0) * 0.5;
        END
        ELSE
        BEGIN
            SET @vlAddLeave = 0;
            SET @slAddLeave = 0;
        END

        -- Prorate balances for employees who became permanent during the year
        IF YEAR(@datePermanent) = @year
        BEGIN
            DECLARE @remainingMonths INT = 12 - MONTH(@datePermanent) + 1;
            SET @balanceVl = (@balanceVl / 12.0) * @remainingMonths;
            SET @balanceSl = (@balanceSl / 12.0) * @remainingMonths;
        END
    END
END;

CREATE PROCEDURE [dbo].[CalculateServiceDetails2]
    @dateOfProbationary DATE,
    @month INT,
    @year INT,
    @employeeStatus NVARCHAR(50),
    @employee_id INT,
    @datePermanent DATE,
    @balanceVl DECIMAL(10, 2) OUTPUT,
    @balanceSl DECIMAL(10, 2) OUTPUT,
    @balanceEl DECIMAL(10, 2) OUTPUT,
    @vlAddLeave DECIMAL(10, 5) OUTPUT,
    @slAddLeave DECIMAL(10, 5) OUTPUT,
    @years INT OUTPUT,
    @months INT OUTPUT,
    @days INT OUTPUT,
    @gainedForceLeave INT OUTPUT
AS

BEGIN
    SET NOCOUNT ON;

    -- 1) Load leave summary into a table variable
    DECLARE @leaveSummary TABLE (
        employee_id       INT,
        year               INT,
        month              INT,
        vacation_leave     FLOAT,
        sick_leave         FLOAT,
        force_leave        FLOAT,
        emergency_leave    FLOAT,
        other_leave        FLOAT,
        addVl              FLOAT,
        addSl              FLOAT,
        balance_vl         FLOAT,
        balance_sl         FLOAT,
        balance_fl         FLOAT,
        balance_el         FLOAT,
        total_absence      FLOAT
    );

    INSERT INTO @leaveSummary
    EXEC [dbo].[GetLeaveSummary] @employee_id, @year;

    -- 2) Fetch the employee’s status
    DECLARE @empStatus NVARCHAR(50);
    SELECT @empStatus = status
      FROM dbo.employee_master
     WHERE employee_id = @employee_id;

    -- 3) Prepare result‑set and cursor
    DECLARE @results TABLE (
        month                INT,
        qualificationMessage NVARCHAR(50)
    );

    DECLARE @month   INT,
            @bVl     FLOAT,
            @bSl     FLOAT,
            @msg     NVARCHAR(50);

    DECLARE leave_cursor CURSOR FOR
    SELECT month, balance_vl, balance_sl
      FROM @leaveSummary
     ORDER BY month;

    OPEN leave_cursor;
    FETCH NEXT FROM leave_cursor INTO @month, @bVl, @bSl;

    -- 4) Loop per‑month and apply logic
    WHILE @@FETCH_STATUS = 0
    BEGIN
        DECLARE @sumVlSl FLOAT = ISNULL(@bVl,0) + ISNULL(@bSl,0);

        IF @empStatus = 'PERMANENT' AND @sumVlSl >= 30
        BEGIN
            SET @msg = 'Qualified';
            -- Insert eligibility record if missing
            IF NOT EXISTS (
                SELECT 1
                  FROM dbo.force_leave_eligibility
                 WHERE emp_id = @employee_id
            )
            BEGIN
                INSERT INTO dbo.force_leave_eligibility
                    (emp_id, [date], cumulative_balance, created_at)
                VALUES
                    (
                        @employee_id,
                        -- first day of the month
                        DATEFROMPARTS(@year, @month, 1),
                        @sumVlSl,
                        GETDATE()
                    );
            END
        END
        ELSE
        BEGIN
            -- If any eligibility record exists at all, treat as Qualified
            IF EXISTS (
                SELECT 1
                  FROM dbo.force_leave_eligibility
                 WHERE emp_id = @employee_id
            )
                SET @msg = 'Qualified';
            ELSE
                SET @msg = 'Not Qualified';
        END

        INSERT INTO @results (month, qualificationMessage)
        VALUES (@month, @msg);

        FETCH NEXT FROM leave_cursor INTO @month, @bVl, @bSl;
    END

    CLOSE leave_cursor;
    DEALLOCATE leave_cursor;

    -- 5) Return final per‑month qualification
    SELECT *
      FROM @results;
END

BEGIN
    SET NOCOUNT ON;

    -- Declare necessary variables
    DECLARE @month INT = 12;
    DECLARE @balanceVl FLOAT = 0;
    DECLARE @balanceSl FLOAT = 0;
    DECLARE @qualifiedMessage NVARCHAR(50);

    -- Fetch the balances for vacation leave and sick leave for the given year and month
    EXEC dbo.GetLeaveSummary @employee_id = @employee_id, @year = @year;

    -- Get the leave balance for December (Month 12)
    SELECT @balanceVl = balance_vl, @balanceSl = balance_sl
    FROM dbo.GetLeaveSummary(@employee_id, @year)
    WHERE month = @month;

    -- Check if balance_vl + balance_sl is greater than or equal to 15
    IF (@balanceVl + @balanceSl) >= 15
    BEGIN
        SET @qualifiedMessage = 'Qualified';
    END
    ELSE
    BEGIN
        SET @qualifiedMessage = 'Not Qualified';
    END

    -- Return the result (qualification message for December)
    SELECT @qualifiedMessage AS QualificationMessage;
END;

BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        DECLARE @currentDate VARCHAR(6) = CONVERT(VARCHAR(6), GETDATE(), 112); -- YYYYMM
        DECLARE @maxSeries INT;
        DECLARE @newBatchCode VARCHAR(12);
        DECLARE @batchId INT;

        -- Get the highest series number for current month from batch table
        SELECT @maxSeries = ISNULL(MAX(CAST(
            CASE 
                WHEN LEN(batch_code) = 12 AND batch_code LIKE 'BA' + @currentDate + '%' 
                THEN SUBSTRING(batch_code, 9, 4) 
                ELSE '0' 
            END AS INT)), 0)
        FROM [dbo].[batch];

        SET @maxSeries = @maxSeries + 1;

        -- Create the batch code
        SET @newBatchCode = 'BA' + @currentDate + RIGHT('0000' + CAST(@maxSeries AS VARCHAR(4)), 4);

        -- Insert into batch table
        --INSERT INTO [dbo].[batch] (
        --    [batch_code],
        --    [batch_name],
        --    [created_by],
        --    [total_applications]
        --) VALUES (
        --    @newBatchCode,
        --    'Batch ' + @newBatchCode,
        --    @createdBy,
        --    0
        --);

        -- Get the inserted batch ID
        SET @batchId = SCOPE_IDENTITY();

        -- Return both batch code and batch ID
        SELECT 
            @newBatchCode AS batch_code,
            @batchId AS batch_id;

    END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        RAISERROR('Error generating batch ID: %s', 16, 1, @ErrorMessage);
    END CATCH
END

BEGIN
    -- Variable to hold the new clearance detail number
    DECLARE @new_cl_dtl_no VARCHAR(50);

    -- Variable to hold the current year
    DECLARE @current_year CHAR(4) = CONVERT(CHAR(4), YEAR(GETDATE()));

    -- Variable to hold the latest auto-incremented number
    DECLARE @latest_number INT;

    -- Find the latest auto-incremented number for the current year with a table lock
    SELECT @latest_number = ISNULL(MAX(CAST(SUBSTRING(cl_dtl_no, 8, 3) AS INT)), 0)
    FROM dbo.clearance_detail WITH (TABLOCKX, HOLDLOCK)
    WHERE SUBSTRING(cl_dtl_no, 4, 4) = @current_year;

    -- Increment the number by 1
    SET @latest_number = @latest_number + 1;

    -- Format the number with leading zeros
    DECLARE @formatted_number CHAR(3) = RIGHT('000' + CAST(@latest_number AS VARCHAR(3)), 3);

    -- Construct the new clearance detail number
    SET @new_cl_dtl_no = 'DTL' + @current_year + @formatted_number;

    -- Return the new clearance detail number
    SELECT @new_cl_dtl_no AS new_cl_dtl_no;
END;

BEGIN
    SET NOCOUNT ON;

    DECLARE @currentYear CHAR(4), @currentMonth CHAR(2), @newTicketID VARCHAR(16), @newSeries INT;
    DECLARE @lastTicketID VARCHAR(50);
    DECLARE @yearMonth CHAR(6);

    -- Get the current year and month as strings
    SET @currentYear = RIGHT('0000' + CAST(YEAR(GETDATE()) AS VARCHAR(4)), 4);
    SET @currentMonth = RIGHT('00' + CAST(MONTH(GETDATE()) AS VARCHAR(2)), 2);
    SET @yearMonth = @currentYear + @currentMonth;

    -- Retrieve the last generated CSR ID
    SELECT TOP 1 @lastTicketID = id
    FROM dbo.csr_applications
    WHERE id LIKE 'CSR%'
    ORDER BY id DESC;

    -- Initialize @newSeries
    SET @newSeries = 0;

    IF @lastTicketID IS NOT NULL AND LEN(@lastTicketID) >= 10
    BEGIN
        DECLARE @lastYearMonth CHAR(6), @lastSeriesStr CHAR(4), @lastSeries INT;

        -- Extract year-month part (positions 4-9: YYYYMM)
        SET @lastYearMonth = SUBSTRING(@lastTicketID, 4, 6);

        -- If current year-month matches last year-month, extract and increment the series
        IF @lastYearMonth = @yearMonth
        BEGIN
            -- Extract series part (positions 10-13: SSSS)
            SET @lastSeriesStr = SUBSTRING(@lastTicketID, 10, 4);

            -- Try to convert to INT
            IF ISNUMERIC(@lastSeriesStr) = 1
            BEGIN
                SET @lastSeries = CAST(@lastSeriesStr AS INT);
                IF @lastSeries IS NOT NULL
                BEGIN
                    SET @newSeries = @lastSeries + 1;
                END
            END
        END
    END

    -- Build initial candidate ID
    SET @newTicketID = 'CSR' + @yearMonth + RIGHT('0000' + CAST(@newSeries AS VARCHAR(4)), 4);

    -- Keep incrementing until we find a unique ID
    WHILE EXISTS (SELECT 1 FROM dbo.csr_applications WHERE id = @newTicketID)
    BEGIN
        SET @newSeries = @newSeries + 1;
        SET @newTicketID = 'CSR' + @yearMonth + RIGHT('0000' + CAST(@newSeries AS VARCHAR(4)), 4);
    END

    SELECT @newTicketID AS NewCSRID;
END

BEGIN
    DECLARE @nextId INT;

    -- Get the next id by counting existing entries
    SELECT @nextId = ISNULL(MAX(CAST(SUBSTRING(ledger_id, 4, 5) AS INT)), 0) + 1
    FROM dbo.ledger;

    -- Format the new ledger_id
    SET @newId = 'LID' + RIGHT('00000' + CAST(@nextId AS VARCHAR(5)), 5);
END

BEGIN
    DECLARE @newId NVARCHAR(8);
    SELECT @newId = 'LID' + RIGHT('00000' + CAST(ISNULL(MAX(CAST(SUBSTRING(ledger_id, 4, 5) AS INT)), 0) + 1 AS NVARCHAR(5)), 5)
    FROM dbo.ledger;

    SELECT @newId AS newId;
END

BEGIN DECLARE @currentYear INT, @currentMonth INT, @newSlipID VARCHAR(12), @newSeries INT; DECLARE @lastSlipID VARCHAR(12);
-- Get the current year and month SET @currentYear = YEAR(GETDATE()); SET @currentMonth = MONTH(GETDATE());
-- Retrieve the last generated Trip Ticket ID SELECT TOP 1 @lastSlipID = trip_id FROM trips WHERE trip_id LIKE 'LO%' ORDER BY trip_id DESC;
-- If no tickets are found, start with the first ticket of this year/month IF @lastSlipID IS NULL BEGIN SET @newSeries = 0; END ELSE BEGIN -- Extract the year, month, and series from the last generated ticket ID DECLARE @lastYear INT, @lastMonth INT, @lastSeries INT;
-- Extract the year and month from the ticket ID SET @lastYear = CAST(SUBSTRING(@lastSlipID, 3, 4) AS INT); -- Extract year from 'TTYYYY' SET @lastMonth = CAST(SUBSTRING(@lastSlipID, 7, 2) AS INT); -- Extract month from 'YYYYMM' SET @lastSeries = CAST(SUBSTRING(@lastSlipID, 9, 4) AS INT); -- Extract series from 'MMSSSS'
-- Check if the month has changed IF @lastYear = @currentYear AND @lastMonth = @currentMonth BEGIN -- Increment the series if in the same month SET @newSeries = @lastSeries + 1; END ELSE BEGIN -- Reset the series to 0000 for a new month SET @newSeries = 0; END END
-- Ensure that the new ticket ID is unique SET @newSlipID = 'LO' + RIGHT('0000' + CAST(@currentYear AS VARCHAR(4)), 4) + RIGHT('00' + CAST(@currentMonth AS VARCHAR(2)), 2) + RIGHT('0000' + CAST(@newSeries AS VARCHAR(4)), 4);
-- Ensure the new ticket ID does not already exist IF EXISTS (SELECT 1 FROM trips WHERE trip_id = @newSlipID) BEGIN -- If the generated ticket ID already exists, increment the series and try again SET @newSeries = @newSeries + 1; SET @newSlipID = 'LO' + RIGHT('0000' + CAST(@currentYear AS VARCHAR(4)), 4) + RIGHT('00' + CAST(@currentMonth AS VARCHAR(2)), 2) + RIGHT('0000' + CAST(@newSeries AS VARCHAR(4)), 4); END
-- Return the new ticket ID SELECT @newSlipID AS NewLocatorSlipID; END

BEGIN
    DECLARE @NewId INT;
    DECLARE @FormattedId VARCHAR(14);
    DECLARE @Year INT;

    SET @Year = YEAR(GETDATE());

    SELECT @NewId = ISNULL(MAX(CAST(SUBSTRING(mntz_app_id, 8, 6) AS INT)), 0) + 1
    FROM monetization_applications
    WHERE mntz_app_id LIKE 'MNT' + CAST(@Year AS VARCHAR(4)) + '%';

    SET @FormattedId = 'MNT' + CAST(@Year AS VARCHAR(4)) + RIGHT('000000' + CAST(@NewId AS VARCHAR(6)), 6);

    SELECT @FormattedId AS NewMonetizationAppId;
END;

BEGIN
    DECLARE @NewId INT;
    DECLARE @FormattedId VARCHAR(14);

    -- Get the next available ID
    SELECT @NewId = ISNULL(MAX(CAST(SUBSTRING(monetize_id, 5, 6) AS INT)), 0) + 1
    FROM monetization_records;

    -- Format the ID with leading zeros
    SET @FormattedId = 'MNTZ' + RIGHT('000000' + CAST(@NewId AS VARCHAR(6)), 6);

    -- Return the new monetize_id
    SELECT @FormattedId AS NewMonetizeId;
END;

BEGIN
    DECLARE @Year VARCHAR(4) = FORMAT(GETDATE(), 'yyyy');
    DECLARE @NextNumber INT;

    -- Find the highest number for the current year
    SELECT @NextNumber = ISNULL(MAX(CAST(SUBSTRING(cl_no, 8, 4) AS INT)), 0) + 1
    FROM dbo.clearance_hdr
    WHERE SUBSTRING(cl_no, 1, 2) = 'CL' AND SUBSTRING(cl_no, 3, 4) = @Year;

    -- Format the new cl_no
    SET @NewClNo = 'CL' + @Year + RIGHT('0000' + CAST(@NextNumber AS VARCHAR(4)), 4);
END;

BEGIN
    DECLARE @currentYear CHAR(4) = CAST(YEAR(GETDATE()) AS CHAR(4));
    DECLARE @nextNumber INT;
    DECLARE @formattedNumber VARCHAR(50);

    -- Get the next sequence number for the current year
    SELECT @nextNumber = ISNULL(MAX(CAST(SUBSTRING(reference_number, 5, 4) AS INT)), 0) + 1
    FROM leave_approvals
    WHERE SUBSTRING(reference_number, 1, 4) = @currentYear;

    -- Format the number with leading zeros
    SET @formattedNumber = @currentYear + RIGHT('0000' + CAST(@nextNumber AS VARCHAR(4)), 4);

    -- Return the new reference number
    SELECT @formattedNumber AS NewReferenceNumber;
END;

BEGIN DECLARE @currentYear INT, @currentMonth INT, @newTravelID VARCHAR(12), @newSeries INT; DECLARE @lastTravelID VARCHAR(12);
-- Get the current year and month SET @currentYear = YEAR(GETDATE()); SET @currentMonth = MONTH(GETDATE());
-- Retrieve the last generated Trip Ticket ID SELECT TOP 1 @lastTravelID = trip_id FROM trips WHERE trip_id LIKE 'TO%' ORDER BY trip_id DESC;
-- If no tickets are found, start with the first ticket of this year/month IF @lastTravelID IS NULL BEGIN SET @newSeries = 0; END ELSE BEGIN -- Extract the year, month, and series from the last generated ticket ID DECLARE @lastYear INT, @lastMonth INT, @lastSeries INT;
-- Extract the year and month from the ticket ID SET @lastYear = CAST(SUBSTRING(@lastTravelID, 3, 4) AS INT); -- Extract year from 'TTYYYY' SET @lastMonth = CAST(SUBSTRING(@lastTravelID, 7, 2) AS INT); -- Extract month from 'YYYYMM' SET @lastSeries = CAST(SUBSTRING(@lastTravelID, 9, 4) AS INT); -- Extract series from 'MMSSSS'
-- Check if the month has changed IF @lastYear = @currentYear AND @lastMonth = @currentMonth BEGIN -- Increment the series if in the same month SET @newSeries = @lastSeries + 1; END ELSE BEGIN -- Reset the series to 0000 for a new month SET @newSeries = 0; END END
-- Ensure that the new ticket ID is unique SET @newTravelID = 'TO' + RIGHT('0000' + CAST(@currentYear AS VARCHAR(4)), 4) + RIGHT('00' + CAST(@currentMonth AS VARCHAR(2)), 2) + RIGHT('0000' + CAST(@newSeries AS VARCHAR(4)), 4);
-- Ensure the new ticket ID does not already exist IF EXISTS (SELECT 1 FROM trips WHERE trip_id = @newTravelID) BEGIN -- If the generated ticket ID already exists, increment the series and try again SET @newSeries = @newSeries + 1; SET @newTravelID = 'TO' + RIGHT('0000' + CAST(@currentYear AS VARCHAR(4)), 4) + RIGHT('00' + CAST(@currentMonth AS VARCHAR(2)), 2) + RIGHT('0000' + CAST(@newSeries AS VARCHAR(4)), 4); END
-- Return the new ticket ID SELECT @newTravelID AS NewTravelOrderID; END

BEGIN DECLARE @currentYear INT, @currentMonth INT, @newTicketID VARCHAR(12), @newSeries INT; DECLARE @lastTicketID VARCHAR(12);
-- Get the current year and month SET @currentYear = YEAR(GETDATE()); SET @currentMonth = MONTH(GETDATE());
-- Retrieve the last generated Trip Ticket ID SELECT TOP 1 @lastTicketID = trip_id FROM trips WHERE trip_id LIKE 'TP%' ORDER BY trip_id DESC;
-- If no tickets are found, start with the first ticket of this year/month IF @lastTicketID IS NULL BEGIN SET @newSeries = 0; END ELSE BEGIN -- Extract the year, month, and series from the last generated ticket ID DECLARE @lastYear INT, @lastMonth INT, @lastSeries INT;
-- Extract the year and month from the ticket ID SET @lastYear = CAST(SUBSTRING(@lastTicketID, 3, 4) AS INT); -- Extract year from 'TTYYYY' SET @lastMonth = CAST(SUBSTRING(@lastTicketID, 7, 2) AS INT); -- Extract month from 'YYYYMM' SET @lastSeries = CAST(SUBSTRING(@lastTicketID, 9, 4) AS INT); -- Extract series from 'MMSSSS'
-- Check if the month has changed IF @lastYear = @currentYear AND @lastMonth = @currentMonth BEGIN -- Increment the series if in the same month SET @newSeries = @lastSeries + 1; END ELSE BEGIN -- Reset the series to 0000 for a new month SET @newSeries = 0; END END
-- Ensure that the new ticket ID is unique SET @newTicketID = 'TP' + RIGHT('0000' + CAST(@currentYear AS VARCHAR(4)), 4) + RIGHT('00' + CAST(@currentMonth AS VARCHAR(2)), 2) + RIGHT('0000' + CAST(@newSeries AS VARCHAR(4)), 4);
-- Ensure the new ticket ID does not already exist IF EXISTS (SELECT 1 FROM trips WHERE trip_id = @newTicketID) BEGIN -- If the generated ticket ID already exists, increment the series and try again SET @newSeries = @newSeries + 1; SET @newTicketID = 'TP' + RIGHT('0000' + CAST(@currentYear AS VARCHAR(4)), 4) + RIGHT('00' + CAST(@currentMonth AS VARCHAR(2)), 2) + RIGHT('0000' + CAST(@newSeries AS VARCHAR(4)), 4); END
-- Return the new ticket ID SELECT @newTicketID AS NewTripTicketID; END

BEGIN
    SET NOCOUNT ON;

    -- Declare variables for balance, leave counts, and other values
    DECLARE @month INT;
    DECLARE @balanceVl FLOAT = 0;
    DECLARE @balanceSl FLOAT = 0;
    DECLARE @balanceFl FLOAT = 0;
    DECLARE @balanceEl FLOAT = 0;
    DECLARE @balanceEls FLOAT = 0;
    DECLARE @addVl FLOAT = 0;
    DECLARE @addSl FLOAT = 0;
    DECLARE @years INT = 0;
    DECLARE @months INT = 0;
    DECLARE @days INT = 0;
    DECLARE @date_hired DATE;
    DECLARE @permanentDate DATE;
    DECLARE @employeeStatus NVARCHAR(50);
    DECLARE @serviceYear INT;
    DECLARE @serviceMonth INT;
    DECLARE @gainedForceLeave INT = 0;
    DECLARE @gainedPercentage NVARCHAR(50);

    -- FORCE LEAVE POLICY VARIABLES
    -- Policy: All employees with 15+ days vacation leave credits must take mandatory leave
    -- (minimum 10 working days annually) OR maintain 30+ days total accumulated leave at year end
    DECLARE @mandatoryVacationThreshold FLOAT = 15.0;
    DECLARE @accumulatedLeaveThreshold FLOAT = 30.0;

    -- DYNAMIC YEAR TRANSITION VARIABLE
    -- Minimum year for which the system started tracking leave records
    -- For any year GREATER than this, include previous year summary
    -- This supports seamless transitions: 2025->2026, 2026->2027, 2027->2028, etc.
    DECLARE @systemMinimumYear INT = 2025;

    -- Fetch the date_hired and employee status for the employee
    SELECT @date_hired = date_hired, @employeeStatus = status, @permanentDate = date_of_permanent
    FROM employee_master
    WHERE employee_id = @employee_id;

    -- Extract the hire year and hire month
    SET @serviceYear = YEAR(@date_hired);
    SET @serviceMonth = MONTH(@date_hired);

    -- Declare the result table
    DECLARE @result TABLE (
        employee_id INT,
        year INT,
        month INT,
        vacation_leave FLOAT,
        sick_leave FLOAT,
        force_leave FLOAT,
        emergency_leave FLOAT,
        other_leave FLOAT,
        addVl FLOAT,
        addSl FLOAT,
        balance_vl FLOAT,
        balance_sl FLOAT,
        balance_fl FLOAT,
        balance_el FLOAT,
        total_absence FLOAT
    );

    -- Calculate initial values using CalculateServiceDetails2
    EXEC CalculateServiceDetails2 
        @dateOfProbationary = @date_hired,
        @datePermanent = @permanentDate,
        @month = 1, 
        @year = @year, 
        @employeeStatus = @employeeStatus,
        @employee_id = @employee_id,
        @balanceVl = @balanceVl OUTPUT,
        @balanceSl = @balanceSl OUTPUT,
        @balanceEl = @balanceEl OUTPUT,
        @vlAddLeave = @addVl OUTPUT,
        @slAddLeave = @addSl OUTPUT,
        @years = @years OUTPUT,
        @months = @months OUTPUT,
        @days = @days OUTPUT,
        @gainedForceLeave = @gainedForceLeave OUTPUT;

    -- Determine the starting month based on the permanent date
    DECLARE @startMonth INT = 1;
    IF YEAR(@permanentDate) = @year
    BEGIN
        SET @startMonth = MONTH(@permanentDate);
    END

    -- Loop through each month from January (1) to December
    SET @month = 1;
    WHILE @month <= 12
    BEGIN
        DECLARE @vacationLeave FLOAT = 0;
        DECLARE @sickLeave FLOAT = 0;
        DECLARE @forceLeaveV FLOAT = 0;
        DECLARE @forceLeaveS FLOAT = 0;
        DECLARE @emergencyLeave FLOAT = 0;
        DECLARE @otherLeave FLOAT = 0;
        DECLARE @totalAbsence FLOAT = 0;
        DECLARE @hollidays FLOAT = 0;
        DECLARE @monetizeVl FLOAT = 0;
        DECLARE @monetizeSl FLOAT = 0;

        -- If the current month is before the start month, set leave counts to 0
        IF @month < @startMonth
        BEGIN
            SET @vacationLeave = 0;
            SET @emergencyLeave = 0;
            SET @sickLeave = 0;
            SET @forceLeaveS = 0;
            SET @forceLeaveV = 0;
            SET @otherLeave = 0;
            SET @totalAbsence = 0;
            SET @balanceVl = 0;
            SET @balanceSl = 0;
            SET @balanceFl = 0; 
            SET @balanceEl = 0;
            SET @balanceEls = 0;
        END
        ELSE
        BEGIN
            -- Get the leave counts for the current month
            SELECT @hollidays = COUNT(*)
            FROM holidays h
            JOIN leave_application la ON h.start_date <= la.end_date AND h.end_date >= la.start_date
            LEFT JOIN employee_address ea ON ea.EmployeeID = la.employee_id
            WHERE la.employee_id = @employee_id 
            AND la.application_status NOT IN ('returned', 'denied')
            AND MONTH(h.start_date) = @month
            AND YEAR(la.date_of_application) = @year
            AND h.start_date BETWEEN la.start_date AND la.end_date;

            SELECT @vacationLeave = COALESCE(SUM(days), 0)
            FROM leave_application la
            LEFT JOIN leave_application_dtl lad ON la.leave_app_id = lad.leave_id
            WHERE la.employee_id = @employee_id 
            AND lad.action = 'VL'
            AND YEAR(lad.leave_date) = @year
            AND MONTH(lad.leave_date) = @month
            AND la.application_status NOT IN ('returned', 'denied');

            SELECT @monetizeVl = COALESCE(SUM(availed_mntz), 0)
            FROM monetization_records 
            WHERE employee_id = @employee_id 
            AND mntz_type = 'VL'
            AND YEAR(mntz_date) = @year;

            SELECT @monetizeSl = COALESCE(SUM(availed_mntz), 0)
            FROM monetization_records 
            WHERE employee_id = @employee_id 
            AND mntz_type = 'SL'
            AND YEAR(mntz_date) = @year;

            SELECT @sickLeave = COALESCE(SUM(days), 0)
            FROM leave_application la
            LEFT JOIN leave_application_dtl lad ON la.leave_app_id = lad.leave_id
            WHERE la.employee_id = @employee_id 
            AND lad.action = 'SL'
            AND YEAR(lad.leave_date) = @year
            AND MONTH(lad.leave_date) = @month
            AND la.application_status NOT IN ('returned', 'denied');

            SELECT @forceLeaveV = COALESCE(SUM(days), 0)
            FROM leave_application la 
            LEFT JOIN leave_application_dtl lad ON la.leave_app_id = lad.leave_id
            WHERE la.employee_id = @employee_id 
            AND lad.[action] = 'FLV'
            AND YEAR(lad.leave_date) = @year 
            AND MONTH(lad.leave_date) = @month
            AND la.application_status NOT IN ('returned', 'denied');

            SELECT @forceLeaveS = COALESCE(SUM(days), 0)
            FROM leave_application la 
            LEFT JOIN leave_application_dtl lad ON la.leave_app_id = lad.leave_id
            WHERE la.employee_id = @employee_id 
            AND lad.[action] = 'FLS'
            AND YEAR(lad.leave_date) = @year 
            AND MONTH(lad.leave_date) = @month
            AND la.application_status NOT IN ('returned', 'denied');

            SELECT @emergencyLeave = COALESCE(SUM(days), 0)
            FROM leave_application la
            LEFT JOIN leave_application_dtl lad ON la.leave_app_id = lad.leave_id
            WHERE la.employee_id = @employee_id
            AND lad.action = 'EL'
            AND YEAR(lad.leave_date) = @year
            AND MONTH(lad.leave_date) = @month
            AND la.application_status NOT IN ('returned', 'denied');

            SELECT @otherLeave = COALESCE(SUM(days), 0)
            FROM leave_application la
            LEFT JOIN leave_application_dtl lad ON la.leave_app_id = lad.leave_id
            WHERE la.employee_id = @employee_id 
            AND lad.action NOT IN ('VL', 'SL', 'SIL', 'EL', 'BL')
            AND YEAR(lad.leave_date) = @year
            AND MONTH(lad.leave_date) = @month
            AND la.application_status NOT IN ('returned', 'denied');

            SELECT @totalAbsence = COALESCE(SUM(days), 0)
            FROM leave_application la
            LEFT JOIN leave_application_dtl lad ON la.leave_app_id = lad.leave_id
            WHERE la.employee_id = @employee_id
            AND YEAR(lad.leave_date) = @year
            AND MONTH(lad.leave_date) = @month
            AND la.application_status NOT IN ('returned', 'denied');

            -- Get gained percentage for the current month
            SELECT @gainedPercentage = [class]
            FROM leave_gained
            WHERE employee_id = @employee_id  
            AND year = @year
            AND month = @month;

            -- For January, get previous year's balances from the ledger
            IF @month = 1
            BEGIN
                IF EXISTS (SELECT 1 FROM ledger WHERE emp_id = @employee_id AND year = @year - 1)
                BEGIN
                    EXEC CalculateServiceDetails2 
                        @dateOfProbationary = @date_hired,
                        @datePermanent = @permanentDate,
                        @month = @month, 
                        @year = @year, 
                        @employeeStatus = @employeeStatus,
                        @employee_id = @employee_id,
                        @balanceVl = @balanceVl OUTPUT,
                        @balanceSl = @balanceSl OUTPUT,
                        @balanceEl = @balanceEl OUTPUT,
                        @vlAddLeave = @addVl OUTPUT,
                        @slAddLeave = @addSl OUTPUT,
                        @years = @years OUTPUT,
                        @months = @months OUTPUT,
                        @days = @days OUTPUT,
                        @gainedForceLeave = @gainedForceLeave OUTPUT;

                    SELECT @balanceVl = balance_vl, @balanceSl = balance_sl
                    FROM ledger 
                    WHERE emp_id = @employee_id 
                    AND year = @year - 1;

                    SET @balanceFl = CASE 
                        WHEN @gainedForceLeave - @forceLeaveS - @forceLeaveV < 0 THEN 0 
                        ELSE @gainedForceLeave - @forceLeaveS - @forceLeaveV
                    END;

                    SET @balanceVl = @balanceVl - @vacationLeave - @forceLeaveV - @monetizeVl + @addVl;
                    SET @balanceSl = @balanceSl - @sickLeave - @forceLeaveS - @monetizeSl + @addSl;
                    SET @balanceEl = @balanceEl + @emergencyLeave;
                END
                ELSE
                BEGIN
                    -- Calculate balance if there's no ledger entry
                    EXEC CalculateServiceDetails2 
                        @dateOfProbationary = @date_hired,
                        @datePermanent = @permanentDate,
                        @month = @month, 
                        @year = @year, 
                        @employeeStatus = @employeeStatus,
                        @employee_id = @employee_id,
                        @balanceVl = @balanceVl OUTPUT,
                        @balanceSl = @balanceSl OUTPUT,
                        @balanceEl = @balanceEl OUTPUT,
                        @vlAddLeave = @addVl OUTPUT,
                        @slAddLeave = @addSl OUTPUT,
                        @years = @years OUTPUT,
                        @months = @months OUTPUT,
                        @days = @days OUTPUT,
                        @gainedForceLeave = @gainedForceLeave OUTPUT;

                    SET @balanceFl = CASE 
                        WHEN @gainedForceLeave - @forceLeaveS - @forceLeaveV < 0 THEN 0 
                        ELSE @gainedForceLeave - @forceLeaveS - @forceLeaveV 
                    END;

                    SET @balanceVl = 0 - @vacationLeave - @forceLeaveV - @monetizeVl + @addVl;
                    SET @balanceSl = 0 - @sickLeave - @forceLeaveS - @monetizeSl + @addSl;
                    SET @balanceEl = @balanceEl + @emergencyLeave;
                END
            END
            ELSE
            BEGIN
                -- For months after January, calculate and carry over the balance
                EXEC CalculateServiceDetails2 
                    @dateOfProbationary = @date_hired,
                    @datePermanent = @permanentDate,
                    @month = @month,
                    @year = @year,
                    @employeeStatus = @employeeStatus,
                    @employee_id = @employee_id,
                    @balanceVl = @balanceVl OUTPUT,
                    @balanceSl = @balanceSl OUTPUT,
                    @balanceEl = @balanceEl OUTPUT,
                    @vlAddLeave = @addVl OUTPUT,
                    @slAddLeave = @addSl OUTPUT,
                    @years = @years OUTPUT,
                    @months = @months OUTPUT,
                    @days = @days OUTPUT,
                    @gainedForceLeave = @gainedForceLeave OUTPUT;

                -- Get last month's balances
                SELECT 
                    @balanceVl = balance_vl,
                    @balanceSl = balance_sl,
                    @balanceFl = balance_fl,
                    @balanceEls = balance_el
                FROM @result
                WHERE employee_id = @employee_id
                AND year = @year
                AND month = @month - 1;

                -- Update force leave balance
                SET @balanceFl = CASE 
                    WHEN @balanceFl > 0 
                        THEN @balanceFl - @forceLeaveS - @forceLeaveV
                    ELSE 0
                END;

                -- Update other leave balances
                SET @balanceVl = @balanceVl - @vacationLeave - @forceLeaveV + @addVl;
                SET @balanceSl = @balanceSl - @sickLeave - @forceLeaveS + @addSl;
                SET @balanceEl = @balanceEls + @emergencyLeave;
            END
        END

        -- Apply custom rounding to balance_vl and balance_sl
        DECLARE @roundedVl FLOAT, @roundedSl FLOAT;

        SET @roundedVl = 
            CASE 
                WHEN @balanceVl - FLOOR(@balanceVl) < 0.13 THEN FLOOR(@balanceVl)
                WHEN @balanceVl - FLOOR(@balanceVl) < 0.38 THEN FLOOR(@balanceVl) + 0.25
                WHEN @balanceVl - FLOOR(@balanceVl) < 0.63 THEN FLOOR(@balanceVl) + 0.50
                WHEN @balanceVl - FLOOR(@balanceVl) < 0.88 THEN FLOOR(@balanceVl) + 0.75
                ELSE CEILING(@balanceVl)
            END;

        SET @roundedSl = 
            CASE 
                WHEN @balanceSl - FLOOR(@balanceSl) < 0.13 THEN FLOOR(@balanceSl)
                WHEN @balanceSl - FLOOR(@balanceSl) < 0.38 THEN FLOOR(@balanceSl) + 0.25
                WHEN @balanceSl - FLOOR(@balanceSl) < 0.63 THEN FLOOR(@balanceSl) + 0.50
                WHEN @balanceSl - FLOOR(@balanceSl) < 0.88 THEN FLOOR(@balanceSl) + 0.75
                ELSE CEILING(@balanceSl)
            END;

        -- Insert the record for the current month into the result table
        INSERT INTO @result (
            employee_id, year, month, vacation_leave, sick_leave, 
            force_leave, emergency_leave, other_leave, addVl, addSl, 
            balance_vl, balance_sl, balance_fl, balance_el, total_absence)
        VALUES (
            @employee_id, @year, @month, @vacationLeave, @sickLeave,
            @balanceFl, @emergencyLeave, @otherLeave, @addVl, @addSl, 
            @balanceVl, @balanceSl, @balanceFl, @balanceEl, @totalAbsence);



        -- Move to the next month
        SET @month = @month + 1;
    END

    -- Get the January (Beginning of Year) balances from the completed result table
    DECLARE @janBalanceVl FLOAT, @janBalanceSl FLOAT;

    SELECT @janBalanceVl = balance_vl, @janBalanceSl = balance_sl
    FROM @result
    WHERE month = 1;

    -- Debug: Check what values we're actually getting
    PRINT 'January (Beginning of Year) Balance VL: ' + CAST(@janBalanceVl AS VARCHAR(10));
    PRINT 'January (Beginning of Year) Balance SL: ' + CAST(@janBalanceSl AS VARCHAR(10));
    PRINT 'Total: ' + CAST((@janBalanceVl + @janBalanceSl) AS VARCHAR(10));

    -- Only proceed if we actually found January data
    IF @janBalanceVl IS NOT NULL AND @janBalanceSl IS NOT NULL
    BEGIN
        -- FORCE LEAVE ELIGIBILITY CHECK (Based on Beginning of Year Balance)
        -- Policy: Employees with 15+ VL AND 30+ total accumulated leave (VL + SL) at year START qualify
        -- Mandatory leave requirement: 10 working days annually for those meeting criteria

        DECLARE @eligibleForForceLeaveBenefit BIT = 0;

        -- Eligibility: VL >= 15 days AND Total balance (VL + SL) >= 30 days (as of January 1st)
        IF @janBalanceVl >= @mandatoryVacationThreshold AND (@janBalanceVl + @janBalanceSl) >= @accumulatedLeaveThreshold
        BEGIN
            SET @eligibleForForceLeaveBenefit = 1;
        END

        IF @eligibleForForceLeaveBenefit = 1
        BEGIN
            -- Check if record already exists for this employee and year
            IF NOT EXISTS (
                SELECT 1 
                FROM force_leave_eligibility 
                WHERE emp_id = @employee_id AND YEAR(date) = @year
            )
            BEGIN
                INSERT INTO force_leave_eligibility (emp_id, date, cumulative_balance, created_at)
                VALUES (
                    @employee_id, 
                    DATEFROMPARTS(@year, 1, 1),
                    @janBalanceVl + @janBalanceSl,
                    GETDATE()
                );

                PRINT 'Force leave eligibility GRANTED - Policy Compliance (Beginning of Year)';
                PRINT 'Employee: ' + CAST(@employee_id AS VARCHAR(10)) + ' | Year: ' + CAST(@year AS VARCHAR(10));
                PRINT 'January 1st Balance: VL >= 15 days (' + CAST(@janBalanceVl AS VARCHAR(10)) + ') AND Total >= 30 days (' + CAST((@janBalanceVl + @janBalanceSl) AS VARCHAR(10)) + ')';
                PRINT 'Mandatory leave notice should be issued by Institutional Services and Administrative Development Division.';
            END
            ELSE
            BEGIN
                PRINT 'Force leave eligibility already exists for employee ' + CAST(@employee_id AS VARCHAR(10)) + ' year ' + CAST(@year AS VARCHAR(10));
            END
        END
        ELSE
        BEGIN
            -- Remove if no longer eligible - does not meet mandatory leave requirement
            DELETE FROM force_leave_eligibility 
            WHERE emp_id = @employee_id AND YEAR(date) = @year;

            PRINT 'Force leave eligibility NOT GRANTED - Does not meet policy requirement at year start';
            PRINT 'Employee: ' + CAST(@employee_id AS VARCHAR(10)) + ' | Year: ' + CAST(@year AS VARCHAR(10));
            PRINT 'January 1st Balance: VL = ' + CAST(@janBalanceVl AS VARCHAR(10)) + ' days (min 15 req) | Total = ' + CAST((@janBalanceVl + @janBalanceSl) AS VARCHAR(10)) + ' days (min 30 req)';
        END
    END
    ELSE
    BEGIN
        PRINT 'No January balance data found for employee ' + CAST(@employee_id AS VARCHAR(10));
    END

    -- Check if we need to include previous year's summary (dynamically based on current year)
    -- For any year GREATER than @systemMinimumYear, include the previous year's summary
    -- This automatically supports year transitions: 2025->2026, 2026->2027, 2027->2028, etc.
    -- To update for a different starting year, modify @systemMinimumYear at the top of the procedure
    IF @year > @systemMinimumYear
    BEGIN
        -- Declare a temporary table for previous year's data
        DECLARE @previousYearResult TABLE (
            employee_id INT,
            year INT,
            month INT,
            vacation_leave FLOAT,
            sick_leave FLOAT,
            force_leave FLOAT,
            emergency_leave FLOAT,
            other_leave FLOAT,
            addVl FLOAT,
            addSl FLOAT,
            balance_vl FLOAT,
            balance_sl FLOAT,
            balance_fl FLOAT,
            balance_el FLOAT,
            total_absence FLOAT
        );

        DECLARE @previousYear INT = @year - 1;

        -- Get the previous year summary from ledger or calculate it
        IF EXISTS (SELECT 1 FROM ledger WHERE emp_id = @employee_id AND year = @previousYear)
        BEGIN
            -- Get the December previous year balance from ledger
            DECLARE @prevYearBalanceVl FLOAT, @prevYearBalanceSl FLOAT;

            SELECT @prevYearBalanceVl = balance_vl, @prevYearBalanceSl = balance_sl
            FROM ledger 
            WHERE emp_id = @employee_id 
            AND year = @previousYear;

            -- Insert a summary row for previous year (using month 0 to indicate it's a summary)
            INSERT INTO @previousYearResult (
                employee_id, year, month, vacation_leave, sick_leave, 
                force_leave, emergency_leave, other_leave, addVl, addSl, 
                balance_vl, balance_sl, balance_fl, balance_el, total_absence)
            VALUES (
                @employee_id, @previousYear, 0,  -- Month 0 indicates yearly summary
                0, 0, 0, 0, 0, 0, 0,    -- Leave details not needed for summary
                @prevYearBalanceVl, @prevYearBalanceSl, 0, 0, 0);
        END
        ELSE
        BEGIN
            -- Try to get previous year's data from force_leave_eligibility or calculate
            DECLARE @prevYearCumulativeBalance FLOAT;

            SELECT @prevYearCumulativeBalance = cumulative_balance
            FROM force_leave_eligibility 
            WHERE emp_id = @employee_id 
            AND YEAR(date) = @previousYear;

            IF @prevYearCumulativeBalance IS NOT NULL
            BEGIN
                -- Insert summary with estimated balances (assuming equal split between VL and SL)
                INSERT INTO @previousYearResult (
                    employee_id, year, month, vacation_leave, sick_leave, 
                    force_leave, emergency_leave, other_leave, addVl, addSl, 
                    balance_vl, balance_sl, balance_fl, balance_el, total_absence)
                VALUES (
                    @employee_id, @previousYear, 0,
                    0, 0, 0, 0, 0, 0, 0,
                    @prevYearCumulativeBalance / 2,  -- Estimated VL balance
                    @prevYearCumulativeBalance / 2,  -- Estimated SL balance
                    0, 0, 0);
            END
        END

        -- Return both current year and previous year summary
        SELECT * FROM @previousYearResult
        UNION ALL
        SELECT * FROM @result
        ORDER BY year DESC, month;
    END
    ELSE
    BEGIN
        -- Return only current year data for year equal to or before @systemMinimumYear
        SELECT * FROM @result
        ORDER BY month;
    END

END;

CREATE PROCEDURE [dbo].[GetLeaveSummary]
    @employee_id INT,
    @year INT,
    @workplace NVARCHAR(10)
AS

BEGIN
    SET NOCOUNT ON;

    -- Declare variables for balance, leave counts, and other values
    DECLARE @month INT;
    DECLARE @balanceVl FLOAT = 0;
    DECLARE @balanceSl FLOAT = 0;
    DECLARE @balanceFl FLOAT = 0;
    DECLARE @balanceEl FLOAT = 0;
    DECLARE @balanceEls FLOAT = 0;
    DECLARE @addVl FLOAT = 0;
    DECLARE @addSl FLOAT = 0;
    DECLARE @years INT = 0;
    DECLARE @months INT = 0;
    DECLARE @days INT = 0;
    DECLARE @date_hired DATE;
    DECLARE @permanentDate DATE;
    DECLARE @employeeStatus NVARCHAR(50);
    DECLARE @serviceYear INT;
    DECLARE @serviceMonth INT;
    DECLARE @gainedForceLeave INT = 0;
    DECLARE @gainedPercentage NVARCHAR(50);

    -- FORCE LEAVE POLICY VARIABLES
    -- Policy: All employees with 15+ days vacation leave credits must take mandatory leave
    -- (minimum 10 working days annually) OR maintain 30+ days total accumulated leave at year end
    DECLARE @mandatoryVacationThreshold FLOAT = 15.0;
    DECLARE @accumulatedLeaveThreshold FLOAT = 30.0;

    -- DYNAMIC YEAR TRANSITION VARIABLE
    -- Minimum year for which the system started tracking leave records
    -- For any year GREATER than this, include previous year summary
    -- This supports seamless transitions: 2025->2026, 2026->2027, 2027->2028, etc.
    DECLARE @systemMinimumYear INT = 2025;

    -- Fetch the date_hired and employee status for the employee
    SELECT @date_hired = date_hired, @employeeStatus = status, @permanentDate = date_of_permanent
    FROM employee_master
    WHERE employee_id = @employee_id;

    -- Extract the hire year and hire month
    SET @serviceYear = YEAR(@date_hired);
    SET @serviceMonth = MONTH(@date_hired);

    -- Declare the result table
    DECLARE @result TABLE (
        employee_id INT,
        year INT,
        month INT,
        vacation_leave FLOAT,
        sick_leave FLOAT,
        force_leave FLOAT,
        emergency_leave FLOAT,
        other_leave FLOAT,
        addVl FLOAT,
        addSl FLOAT,
        balance_vl FLOAT,
        balance_sl FLOAT,
        balance_fl FLOAT,
        balance_el FLOAT,
        total_absence FLOAT
    );

    -- Calculate initial values using CalculateServiceDetails2
    --
    EXEC CalculateServiceDetails2 
        @dateOfProbationary = @date_hired,
        @datePermanent = @permanentDate,
        @month = 1, 
        @year = @year, 
        @employeeStatus = @employeeStatus,
        @employee_id = @employee_id,
        @balanceVl = @balanceVl OUTPUT,
        @balanceSl = @balanceSl OUTPUT,
        @balanceEl = @balanceEl OUTPUT,
        @vlAddLeave = @addVl OUTPUT,
        @slAddLeave = @addSl OUTPUT,
        @years = @years OUTPUT,
        @months = @months OUTPUT,
        @days = @days OUTPUT,
        @gainedForceLeave = @gainedForceLeave OUTPUT;


    DECLARE @startMonth INT = 1;
    IF YEAR(@permanentDate) = @year
    BEGIN
        SET @startMonth = MONTH(@permanentDate);
    END

    -- Loop through each month from January (1) to December
    SET @month = 1;
    WHILE @month <= 12
    BEGIN
        DECLARE @vacationLeave FLOAT = 0;
        DECLARE @sickLeave FLOAT = 0;
        DECLARE @forceLeaveV FLOAT = 0;
        DECLARE @forceLeaveS FLOAT = 0;
        DECLARE @emergencyLeave FLOAT = 0;
        DECLARE @otherLeave FLOAT = 0;
        DECLARE @totalAbsence FLOAT = 0;
        DECLARE @hollidays FLOAT = 0;
        DECLARE @monetizeVl FLOAT = 0;
        DECLARE @monetizeSl FLOAT = 0;

        -- If the current month is before the start month, set leave counts to 0
        IF @month < @startMonth
        BEGIN
            SET @vacationLeave = 0;
            SET @emergencyLeave = 0;
            SET @sickLeave = 0;
            SET @forceLeaveS = 0;
            SET @forceLeaveV = 0;
            SET @otherLeave = 0;
            SET @totalAbsence = 0;
            SET @balanceVl = 0;
            SET @balanceSl = 0;
            SET @balanceFl = 0; 
            SET @balanceEl = 0;
            SET @balanceEls = 0;
        END
        ELSE
        BEGIN
            -- Get the leave counts for the current month
            SELECT @hollidays = COUNT(*)
            FROM holidays h
            JOIN leave_application la ON h.start_date <= la.end_date AND h.end_date >= la.start_date
            LEFT JOIN employee_address ea ON ea.EmployeeID = la.employee_id
            WHERE la.employee_id = @employee_id 
            AND la.application_status NOT IN ('returned', 'denied')
            AND MONTH(h.start_date) = @month
            AND YEAR(la.date_of_application) = @year
            AND h.start_date BETWEEN la.start_date AND la.end_date;

            SELECT @vacationLeave = COALESCE(SUM(days), 0)
            FROM leave_application la
            LEFT JOIN leave_application_dtl lad ON la.leave_app_id = lad.leave_id
            WHERE la.employee_id = @employee_id 
            AND lad.action = 'VL'
            AND YEAR(lad.leave_date) = @year
            AND MONTH(lad.leave_date) = @month
            AND la.application_status NOT IN ('returned', 'denied');

            SELECT @monetizeVl = COALESCE(SUM(availed_mntz), 0)
            FROM monetization_records 
            WHERE employee_id = @employee_id 
            AND mntz_type = 'VL'
            AND YEAR(mntz_date) = @year;

            SELECT @monetizeSl = COALESCE(SUM(availed_mntz), 0)
            FROM monetization_records 
            WHERE employee_id = @employee_id 
            AND mntz_type = 'SL'
            AND YEAR(mntz_date) = @year;

            SELECT @sickLeave = COALESCE(SUM(days), 0)
            FROM leave_application la
            LEFT JOIN leave_application_dtl lad ON la.leave_app_id = lad.leave_id
            WHERE la.employee_id = @employee_id 
            AND lad.action = 'SL'
            AND YEAR(lad.leave_date) = @year
            AND MONTH(lad.leave_date) = @month
            AND la.application_status NOT IN ('returned', 'denied');

            SELECT @forceLeaveV = COALESCE(SUM(days), 0)
            FROM leave_application la 
            LEFT JOIN leave_application_dtl lad ON la.leave_app_id = lad.leave_id
            WHERE la.employee_id = @employee_id 
            AND lad.[action] = 'FLV'
            AND YEAR(lad.leave_date) = @year 
            AND MONTH(lad.leave_date) = @month
            AND la.application_status NOT IN ('returned', 'denied');

            SELECT @forceLeaveS = COALESCE(SUM(days), 0)
            FROM leave_application la 
            LEFT JOIN leave_application_dtl lad ON la.leave_app_id = lad.leave_id
            WHERE la.employee_id = @employee_id 
            AND lad.[action] = 'FLS'
            AND YEAR(lad.leave_date) = @year 
            AND MONTH(lad.leave_date) = @month
            AND la.application_status NOT IN ('returned', 'denied');

            SELECT @emergencyLeave = COALESCE(SUM(days), 0)
            FROM leave_application la
            LEFT JOIN leave_application_dtl lad ON la.leave_app_id = lad.leave_id
            WHERE la.employee_id = @employee_id
            AND lad.action = 'EL'
            AND YEAR(lad.leave_date) = @year
            AND MONTH(lad.leave_date) = @month
            AND la.application_status NOT IN ('returned', 'denied');

            SELECT @otherLeave = COALESCE(SUM(days), 0)
            FROM leave_application la
            LEFT JOIN leave_application_dtl lad ON la.leave_app_id = lad.leave_id
            WHERE la.employee_id = @employee_id 
            AND lad.action NOT IN ('VL', 'SL', 'SIL', 'EL', 'BL')
            AND YEAR(lad.leave_date) = @year
            AND MONTH(lad.leave_date) = @month
            AND la.application_status NOT IN ('returned', 'denied');

            SELECT @totalAbsence = COALESCE(SUM(days), 0)
            FROM leave_application la
            LEFT JOIN leave_application_dtl lad ON la.leave_app_id = lad.leave_id
            WHERE la.employee_id = @employee_id
            AND YEAR(lad.leave_date) = @year
            AND MONTH(lad.leave_date) = @month
            AND la.application_status NOT IN ('returned', 'denied');

            -- Get gained percentage for the current month
            SELECT @gainedPercentage = [class]
            FROM leave_gained
            WHERE employee_id = @employee_id  
            AND year = @year
            AND month = @month;

            -- For January, get previous year's balances from the ledger
            IF @month = 1
            BEGIN
                IF EXISTS (SELECT 1 FROM ledger WHERE emp_id = @employee_id AND year = @year - 1)
                BEGIN
                    EXEC CalculateServiceDetails2 
                        @dateOfProbationary = @date_hired,
                        @datePermanent = @permanentDate,
                        @month = @month, 
                        @year = @year, 
                        @employeeStatus = @employeeStatus,
                        @employee_id = @employee_id,
                        @balanceVl = @balanceVl OUTPUT,
                        @balanceSl = @balanceSl OUTPUT,
                        @balanceEl = @balanceEl OUTPUT,
                        @vlAddLeave = @addVl OUTPUT,
                        @slAddLeave = @addSl OUTPUT,
                        @years = @years OUTPUT,
                        @months = @months OUTPUT,
                        @days = @days OUTPUT,
                        @gainedForceLeave = @gainedForceLeave OUTPUT;

                    SELECT @balanceVl = balance_vl, @balanceSl = balance_sl
                    FROM ledger 
                    WHERE emp_id = @employee_id 
                    AND year = @year - 1;

                    SET @balanceFl = CASE 
                        WHEN @gainedForceLeave - @forceLeaveS - @forceLeaveV < 0 THEN 0 
                        ELSE @gainedForceLeave - @forceLeaveS - @forceLeaveV
                    END;

                    SET @balanceVl = @balanceVl - @vacationLeave - @forceLeaveV - @monetizeVl + @addVl;
                    SET @balanceSl = @balanceSl - @sickLeave - @forceLeaveS - @monetizeSl + @addSl;
                    SET @balanceEl = @balanceEl + @emergencyLeave;
                END
                ELSE
                BEGIN
                    -- Calculate balance if there's no ledger entry
                    EXEC CalculateServiceDetails2 
                        @dateOfProbationary = @date_hired,
                        @datePermanent = @permanentDate,
                        @month = @month, 
                        @year = @year, 
                        @employeeStatus = @employeeStatus,
                        @employee_id = @employee_id,
                        @balanceVl = @balanceVl OUTPUT,
                        @balanceSl = @balanceSl OUTPUT,
                        @balanceEl = @balanceEl OUTPUT,
                        @vlAddLeave = @addVl OUTPUT,
                        @slAddLeave = @addSl OUTPUT,
                        @years = @years OUTPUT,
                        @months = @months OUTPUT,
                        @days = @days OUTPUT,
                        @gainedForceLeave = @gainedForceLeave OUTPUT;

                    SET @balanceFl = CASE 
                        WHEN @gainedForceLeave - @forceLeaveS - @forceLeaveV < 0 THEN 0 
                        ELSE @gainedForceLeave - @forceLeaveS - @forceLeaveV 
                    END;

                    SET @balanceVl = 0 - @vacationLeave - @forceLeaveV - @monetizeVl + @addVl;
                    SET @balanceSl = 0 - @sickLeave - @forceLeaveS - @monetizeSl + @addSl;
                    SET @balanceEl = @balanceEl + @emergencyLeave;
                END
            END
            ELSE
            BEGIN
                -- For months after January, calculate and carry over the balance
                EXEC CalculateServiceDetails2 
                    @dateOfProbationary = @date_hired,
                    @datePermanent = @permanentDate,
                    @month = @month,
                    @year = @year,
                    @employeeStatus = @employeeStatus,
                    @employee_id = @employee_id,
                    @balanceVl = @balanceVl OUTPUT,
                    @balanceSl = @balanceSl OUTPUT,
                    @balanceEl = @balanceEl OUTPUT,
                    @vlAddLeave = @addVl OUTPUT,
                    @slAddLeave = @addSl OUTPUT,
                    @years = @years OUTPUT,
                    @months = @months OUTPUT,
                    @days = @days OUTPUT,
                    @gainedForceLeave = @gainedForceLeave OUTPUT;

                -- Get last month's balances
                SELECT 
                    @balanceVl = balance_vl,
                    @balanceSl = balance_sl,
                    @balanceFl = balance_fl,
                    @balanceEls = balance_el
                FROM @result
                WHERE employee_id = @employee_id
                AND year = @year
                AND month = @month - 1;

                -- Update force leave balance
                SET @balanceFl = CASE 
                    WHEN @balanceFl > 0 
                        THEN @balanceFl - @forceLeaveS - @forceLeaveV
                    ELSE 0
                END;

                -- Update other leave balances
                SET @balanceVl = @balanceVl - @vacationLeave - @forceLeaveV + @addVl;
                SET @balanceSl = @balanceSl - @sickLeave - @forceLeaveS + @addSl;
                SET @balanceEl = @balanceEls + @emergencyLeave;
            END
        END

        -- Apply custom rounding to balance_vl and balance_sl
        DECLARE @roundedVl FLOAT, @roundedSl FLOAT;

        SET @roundedVl = 
            CASE 
                WHEN @balanceVl - FLOOR(@balanceVl) < 0.13 THEN FLOOR(@balanceVl)
                WHEN @balanceVl - FLOOR(@balanceVl) < 0.38 THEN FLOOR(@balanceVl) + 0.25
                WHEN @balanceVl - FLOOR(@balanceVl) < 0.63 THEN FLOOR(@balanceVl) + 0.50
                WHEN @balanceVl - FLOOR(@balanceVl) < 0.88 THEN FLOOR(@balanceVl) + 0.75
                ELSE CEILING(@balanceVl)
            END;

        SET @roundedSl = 
            CASE 
                WHEN @balanceSl - FLOOR(@balanceSl) < 0.13 THEN FLOOR(@balanceSl)
                WHEN @balanceSl - FLOOR(@balanceSl) < 0.38 THEN FLOOR(@balanceSl) + 0.25
                WHEN @balanceSl - FLOOR(@balanceSl) < 0.63 THEN FLOOR(@balanceSl) + 0.50
                WHEN @balanceSl - FLOOR(@balanceSl) < 0.88 THEN FLOOR(@balanceSl) + 0.75
                ELSE CEILING(@balanceSl)
            END;

        -- Insert the record for the current month into the result table
        INSERT INTO @result (
            employee_id, year, month, vacation_leave, sick_leave, 
            force_leave, emergency_leave, other_leave, addVl, addSl, 
            balance_vl, balance_sl, balance_fl, balance_el, total_absence)
        VALUES (
            @employee_id, @year, @month, @vacationLeave, @sickLeave,
            @balanceFl, @emergencyLeave, @otherLeave, @addVl, @addSl, 
            @balanceVl, @balanceSl, @balanceFl, @balanceEl, @totalAbsence);

        -- Move to the next month
        SET @month = @month + 1;
    END

    -- Get the January (Beginning of Year) balances from the completed result table
    DECLARE @janBalanceVl FLOAT, @janBalanceSl FLOAT;

    SELECT @janBalanceVl = balance_vl, @janBalanceSl = balance_sl
    FROM @result
    WHERE month = 1;

    -- Debug: Check what values we're actually getting
    PRINT 'January (Beginning of Year) Balance VL: ' + CAST(@janBalanceVl AS VARCHAR(10));
    PRINT 'January (Beginning of Year) Balance SL: ' + CAST(@janBalanceSl AS VARCHAR(10));
    PRINT 'Total: ' + CAST((@janBalanceVl + @janBalanceSl) AS VARCHAR(10));

    -- Only proceed if we actually found January data
    IF @janBalanceVl IS NOT NULL AND @janBalanceSl IS NOT NULL
    BEGIN
        -- FORCE LEAVE ELIGIBILITY CHECK (Based on Beginning of Year Balance)
        -- Policy: Employees with 15+ VL AND 30+ total accumulated leave (VL + SL) at year START qualify
        -- Mandatory leave requirement: 10 working days annually for those meeting criteria

        DECLARE @eligibleForForceLeaveBenefit BIT = 0;

        -- Eligibility: VL >= 15 days AND Total balance (VL + SL) >= 30 days (as of January 1st)
        IF @janBalanceVl >= @mandatoryVacationThreshold AND (@janBalanceVl + @janBalanceSl) >= @accumulatedLeaveThreshold
        BEGIN
            SET @eligibleForForceLeaveBenefit = 1;
        END

        IF @eligibleForForceLeaveBenefit = 1
        BEGIN
            -- Check if record already exists for this employee and year
            IF NOT EXISTS (
                SELECT 1 
                FROM force_leave_eligibility 
                WHERE emp_id = @employee_id AND YEAR(date) = @year
            )
            BEGIN
                INSERT INTO force_leave_eligibility (emp_id, date, cumulative_balance, created_at)
                VALUES (
                    @employee_id, 
                    DATEFROMPARTS(@year, 1, 1),
                    @janBalanceVl + @janBalanceSl,
                    GETDATE()
                );

                PRINT 'Force leave eligibility GRANTED - Policy Compliance (Beginning of Year)';
                PRINT 'Employee: ' + CAST(@employee_id AS VARCHAR(10)) + ' | Year: ' + CAST(@year AS VARCHAR(10));
                PRINT 'January 1st Balance: VL >= 15 days (' + CAST(@janBalanceVl AS VARCHAR(10)) + ') AND Total >= 30 days (' + CAST((@janBalanceVl + @janBalanceSl) AS VARCHAR(10)) + ')';
                PRINT 'Mandatory leave notice should be issued by Institutional Services and Administrative Development Division.';
            END
            ELSE
            BEGIN
                PRINT 'Force leave eligibility already exists for employee ' + CAST(@employee_id AS VARCHAR(10)) + ' year ' + CAST(@year AS VARCHAR(10));
            END
        END
        ELSE
        BEGIN
            -- Remove if no longer eligible - does not meet mandatory leave requirement
            -- Why there is static year? iwant this to be dynamic base on the 
            DELETE FROM force_leave_eligibility 
            WHERE emp_id = @employee_id AND YEAR(date) = @year;

            PRINT 'Force leave eligibility NOT GRANTED - Does not meet policy requirement at year start';
            PRINT 'Employee: ' + CAST(@employee_id AS VARCHAR(10)) + ' | Year: ' + CAST(@year AS VARCHAR(10));
            PRINT 'January 1st Balance: VL = ' + CAST(@janBalanceVl AS VARCHAR(10)) + ' days (min 15 req) | Total = ' + CAST((@janBalanceVl + @janBalanceSl) AS VARCHAR(10)) + ' days (min 30 req)';
        END
    END
    ELSE
    BEGIN
        PRINT 'No January balance data found for employee ' + CAST(@employee_id AS VARCHAR(10));
    END

    -- Check if we need to include previous year's summary (dynamically based on current year)
    -- For any year GREATER than @systemMinimumYear, include the previous year's summary
    -- This automatically supports year transitions: 2025->2026, 2026->2027, 2027->2028, etc.
    -- To update for a different starting year, modify @systemMinimumYear at the top of the procedure
    IF @year > @systemMinimumYear
    BEGIN
        -- Declare a temporary table for previous year's data
        DECLARE @previousYearResult TABLE (
            employee_id INT,
            year INT,
            month INT,
            vacation_leave FLOAT,
            sick_leave FLOAT,
            force_leave FLOAT,
            emergency_leave FLOAT,
            other_leave FLOAT,
            addVl FLOAT,
            addSl FLOAT,
            balance_vl FLOAT,
            balance_sl FLOAT,
            balance_fl FLOAT,
            balance_el FLOAT,
            total_absence FLOAT
        );

        DECLARE @previousYear INT = @year - 1;

        -- Get the previous year summary from ledger or calculate it
        IF EXISTS (SELECT 1 FROM ledger WHERE emp_id = @employee_id AND year = @previousYear)
        BEGIN
            -- Get the December previous year balance from ledger
            DECLARE @prevYearBalanceVl FLOAT, @prevYearBalanceSl FLOAT;

            SELECT @prevYearBalanceVl = balance_vl, @prevYearBalanceSl = balance_sl
            FROM ledger 
            WHERE emp_id = @employee_id 
            AND year = @previousYear;

            -- Insert a summary row for previous year (using month 0 to indicate it's a summary)
            INSERT INTO @previousYearResult (
                employee_id, year, month, vacation_leave, sick_leave, 
                force_leave, emergency_leave, other_leave, addVl, addSl, 
                balance_vl, balance_sl, balance_fl, balance_el, total_absence)
            VALUES (
                @employee_id, @previousYear, 0,  -- Month 0 indicates yearly summary
                0, 0, 0, 0, 0, 0, 0,    -- Leave details not needed for summary
                @prevYearBalanceVl, @prevYearBalanceSl, 0, 0, 0);
        END
        ELSE
        BEGIN
            -- Try to get previous year's data from force_leave_eligibility or calculate
            DECLARE @prevYearCumulativeBalance FLOAT;

            SELECT @prevYearCumulativeBalance = cumulative_balance
            FROM force_leave_eligibility 
            WHERE emp_id = @employee_id 
            AND YEAR(date) = @previousYear;

            IF @prevYearCumulativeBalance IS NOT NULL
            BEGIN
                -- Insert summary with estimated balances (assuming equal split between VL and SL)
                INSERT INTO @previousYearResult (
                    employee_id, year, month, vacation_leave, sick_leave, 
                    force_leave, emergency_leave, other_leave, addVl, addSl, 
                    balance_vl, balance_sl, balance_fl, balance_el, total_absence)
                VALUES (
                    @employee_id, @previousYear, 0,
                    0, 0, 0, 0, 0, 0, 0,
                    @prevYearCumulativeBalance / 2,  -- Estimated VL balance
                    @prevYearCumulativeBalance / 2,  -- Estimated SL balance
                    0, 0, 0);
            END
        END

        -- Return both current year and previous year summary
        SELECT * FROM @previousYearResult
        UNION ALL
        SELECT * FROM @result
        ORDER BY year DESC, month;
    END
    ELSE
    BEGIN
        -- Return only current year data for year equal to or before @systemMinimumYear
        SELECT * FROM @result
        ORDER BY month;
    END
END;

CREATE PROCEDURE [dbo].[GetLeaveSummarySync]
    @employee_id INT,
    @year INT,
    @workplace NVARCHAR(10)
AS

BEGIN -- Declare a table variable to store the end of month totals for balance_vl and balance_sl DECLARE @leaveSummary TABLE ( emp_id INT, year INT, month INT, balance_vl FLOAT, balance_sl FLOAT, total_balance FLOAT );
-- Declare a cursor to loop over employees in the employee_master table DECLARE employee_cursor CURSOR FOR SELECT em.employee_id FROM employee_master em WHERE status = 'permanent'; -- You can adjust this condition as needed (e.g., only active employees)
DECLARE @employee_id INT; DECLARE @year INT = 2025; -- Replace with the desired year DECLARE @month INT = 3; -- Replace with the desired month, or you can dynamically pass it to the procedure
-- Open the cursor OPEN employee_cursor;
-- Fetch the first employee FETCH NEXT FROM employee_cursor INTO @employee_id;
-- Loop over all employees WHILE @@FETCH_STATUS = 0 BEGIN -- Call the GetLeaveSummary stored procedure to populate the leave summary table for the current employee INSERT INTO @leaveSummary (emp_id, year, month, balance_vl, balance_sl, total_balance) EXEC dbo.GetLeaveSummary @employee_id, @year;
-- Insert into force_leave_eligibility if total balance is >= 15 and emp_id is not already in the table INSERT INTO [dbo].[force_leave_eligibility] ([emp_id], [date], [cumulative_balance]) SELECT ls.emp_id, GETDATE(), -- You can replace GETDATE() with any date column if necessary ls.total_balance FROM @leaveSummary ls WHERE ls.total_balance >= 15 AND NOT EXISTS ( SELECT 1 FROM [dbo].[force_leave_eligibility] WHERE [emp_id] = ls.emp_id );
-- Fetch the next employee FETCH NEXT FROM employee_cursor INTO @employee_id; END
-- Close and deallocate the cursor CLOSE employee_cursor; DEALLOCATE employee_cursor;
END;

BEGIN
    SET NOCOUNT ON;

    DECLARE @employee_id INT;
    DECLARE @year INT = YEAR(GETDATE());  -- Get the current year
    DECLARE @total_balance FLOAT;
    DECLARE @vacation_leave FLOAT;
    DECLARE @sick_leave FLOAT;
    DECLARE @force_leave FLOAT;
    DECLARE @emergency_leave FLOAT;
    DECLARE @other_leave FLOAT;
    DECLARE @created_at DATETIME = GETDATE();

    -- Declare @result table variable to store the result from GetLeaveSummary
    DECLARE @result TABLE (
        employee_id INT,
        year INT,
        month INT,
        vacation_leave FLOAT,
        sick_leave FLOAT,
        force_leave FLOAT,
        emergency_leave FLOAT,
        other_leave FLOAT,
        addVl FLOAT,
        addSl FLOAT,
        balance_vl FLOAT,
        balance_sl FLOAT,
        balance_fl FLOAT,
        balance_el FLOAT,
        total_absence FLOAT
    );

    -- Cursor to loop through active employees in employee_master table
    DECLARE employee_cursor CURSOR FOR
    SELECT employee_id
    FROM employee_master
    WHERE status = 'Active';  -- Only for active employees

    OPEN employee_cursor;

    FETCH NEXT FROM employee_cursor INTO @employee_id;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        -- Insert the result of GetLeaveSummary into @result table
        INSERT INTO @result (employee_id, year, month, vacation_leave, sick_leave, force_leave, emergency_leave, other_leave, addVl, addSl, balance_vl, balance_sl, balance_fl, balance_el, total_absence)
        EXEC [dbo].[GetLeaveSummary]
            @employee_id = @employee_id,
            @year = @year;

        -- Assuming the last month of the result (December) contains the final balances
        SELECT TOP 1
            @vacation_leave = balance_vl,
            @sick_leave = balance_sl,
            @force_leave = balance_fl,
            @emergency_leave = balance_el,
            @other_leave = other_leave
        FROM @result  -- @result is returned by GetLeaveSummary
        WHERE year = @year AND month = 12;

        -- Calculate the total balance (vacation + sick leave)
        SET @total_balance = @vacation_leave + @sick_leave;

        -- Insert into force_leave_eligibility table if the total balance is >= 15
        IF @total_balance >= 15
        BEGIN
            -- Ensure no record already exists for this employee and year
            IF NOT EXISTS (SELECT 1 FROM force_leave_eligibility WHERE emp_id = @employee_id AND YEAR(date) = @year)
            BEGIN
                -- Insert the record into force_leave_eligibility table for the current year
                INSERT INTO force_leave_eligibility (emp_id, [date], cumulative_balance, created_at)
                VALUES (@employee_id, CAST(CONCAT(@year, '-12-31') AS DATE), @total_balance, @created_at);
            END
        END

        FETCH NEXT FROM employee_cursor INTO @employee_id;
    END

    CLOSE employee_cursor;
    DEALLOCATE employee_cursor;

END

BEGIN
    SET NOCOUNT ON;

    -- Temporary table to hold the leave summary
    DECLARE @LeaveSummary TABLE (
        employee_id INT,
        year INT,
        month INT,
        balance_vl FLOAT,
        balance_sl FLOAT
    );

    -- Insert leave summary into temporary table
    INSERT INTO @LeaveSummary
    EXEC GetLeaveSummary @employee_id, @year;

    -- Check December balance_vl and balance_sl
    DECLARE @balance_vl FLOAT, @balance_sl FLOAT;

    SELECT @balance_vl = balance_vl, @balance_sl = balance_sl
    FROM @LeaveSummary
    WHERE month = 12;

    -- If both are >= 15, insert into force_leave_eligibility
    IF @balance_vl >= 15 AND @balance_sl >= 15
    BEGIN
        INSERT INTO force_leave_eligibility (emp_id, date, cumulative_balance, created_at)
        VALUES (@employee_id, GETDATE(), @balance_vl + @balance_sl, GETDATE());
    END
END;

CREATE PROCEDURE InsertForceLeaveEligibility
    @employee_id INT,
    @year INT
AS

BEGIN
DECLARE @prefix VARCHAR(2) = LEFT(@tt_id, 2);
IF @prefix = 'TO' BEGIN -- Insert only the general manager (assuming plantilla_code = 1 is GM, adjust as needed) DECLARE @gm_emp_id VARCHAR(10); SELECT TOP 1 @gm_emp_id = employee_id FROM employee_master WHERE plantilla_code = '2016000'; IF @gm_emp_id IS NOT NULL BEGIN IF NOT EXISTS (SELECT 1 FROM outbound_approval WHERE outbound_code = @tt_id AND approver_id = @gm_emp_id) BEGIN INSERT INTO outbound_approval (outbound_code, approver_id, approval_status, approval_date) VALUES (@tt_id, @gm_emp_id, 'Pending', NULL); END END RETURN; END
DECLARE @employee_id VARCHAR(10); DECLARE @dept_code VARCHAR(10); DECLARE @manager VARCHAR(10); DECLARE @approval_status VARCHAR(50) = 'Pending'; DECLARE @approval_date DATE = NULL; -- This will be set later when approved
-- Temporary table to store approver employee_ids DECLARE @roles TABLE (approver_id VARCHAR(10));
-- Cursor to fetch employee details from trip_passenger DECLARE approval_cursor CURSOR FOR SELECT p.employee_id FROM trip_passenger p WHERE p.tt_id = @tt_id;
OPEN approval_cursor; FETCH NEXT FROM approval_cursor INTO @employee_id;
WHILE @@FETCH_STATUS = 0 BEGIN -- Retrieve the dept_code for the current employee_id SELECT @dept_code = e.dept_code FROM employee_master e WHERE e.employee_id = @employee_id;
-- Retrieve the manager's plantilla_code based on dept_code SELECT TOP 1 @manager = d.manager -- Manager plantilla_code from department FROM department d WHERE d.dept_code = @dept_code;
-- Insert all possible roles (officer, supervisor, foreman, concerned_imos) as employee_id INSERT INTO @roles (approver_id) SELECT DISTINCT em2.employee_id FROM plantilla p JOIN employee_master e ON e.plantilla_code = p.plantilla_code JOIN employee_master em2 ON em2.plantilla_code = p.foreman WHERE e.employee_id = @employee_id AND p.foreman IS NOT NULL AND p.foreman <> 0
UNION
SELECT DISTINCT em2.employee_id FROM plantilla p JOIN employee_master e ON e.plantilla_code = p.plantilla_code JOIN employee_master em2 ON em2.plantilla_code = p.officer WHERE e.employee_id = @employee_id AND p.officer IS NOT NULL AND p.officer <> 0
UNION
SELECT DISTINCT em2.employee_id FROM plantilla p JOIN employee_master e ON e.plantilla_code = p.plantilla_code JOIN employee_master em2 ON em2.plantilla_code = p.supervisor WHERE e.employee_id = @employee_id AND p.supervisor IS NOT NULL AND p.supervisor <> 0
UNION
SELECT DISTINCT em2.employee_id FROM plantilla p JOIN employee_master e ON e.plantilla_code = p.plantilla_code JOIN employee_master em2 ON em2.plantilla_code = p.concerned_imos WHERE e.employee_id = @employee_id AND p.concerned_imos IS NOT NULL AND p.concerned_imos <> 0;
-- Loop through all inserted roles and insert them into outbound_approval DECLARE @role_id VARCHAR(10);
DECLARE role_cursor CURSOR FOR SELECT approver_id FROM @roles;
OPEN role_cursor; FETCH NEXT FROM role_cursor INTO @role_id;
WHILE @@FETCH_STATUS = 0 BEGIN -- Insert each role as an approver if it doesn't already exist IF NOT EXISTS (SELECT 1 FROM outbound_approval WHERE outbound_code = @tt_id AND approver_id = @role_id) BEGIN INSERT INTO outbound_approval (outbound_code, approver_id, approval_status, approval_date) VALUES (@tt_id, @role_id, @approval_status, @approval_date); END
FETCH NEXT FROM role_cursor INTO @role_id; END
CLOSE role_cursor; DEALLOCATE role_cursor;
-- Insert manager approval if found and not already present IF @manager IS NOT NULL BEGIN DECLARE @manager_emp_id VARCHAR(10); SELECT TOP 1 @manager_emp_id = employee_id FROM employee_master WHERE plantilla_code = @manager; IF @manager_emp_id IS NOT NULL BEGIN IF NOT EXISTS (SELECT 1 FROM outbound_approval WHERE outbound_code = @tt_id AND approver_id = @manager_emp_id) BEGIN INSERT INTO outbound_approval (outbound_code, approver_id, approval_status, approval_date) VALUES (@tt_id, @manager_emp_id, @approval_status, @approval_date); END END END
FETCH NEXT FROM approval_cursor INTO @employee_id; END
CLOSE approval_cursor; DEALLOCATE approval_cursor; END
--if tt_id starts with TT AND LO, nothing changes, IF TO insert only the general manager

