-- Insert all possible roles (officer, supervisor, foreman, concerned_imos) as employee_id INSERT INTO @roles (approver_id) SELECT DISTINCT em2.employee_id FROM plantilla p JOIN employee_master e ON e.plantilla_code = p.plantilla_code JOIN employee_master em2 ON em2.plantilla_code = p.foreman WHERE e.new_employee_id = @employee_id AND p.foreman IS NOT NULL AND p.foreman <> 0
