SELECT DISTINCT em2.employee_id FROM plantilla p JOIN employee_master e ON e.plantilla_code = p.plantilla_code JOIN employee_master em2 ON em2.plantilla_code = p.officer WHERE e.new_employee_id = @employee_id AND p.officer IS NOT NULL AND p.officer <> 0
