CREATE PROCEDURE [dbo].[InsertOutboundApprovalOvertime]
    @tt_id VARCHAR(15)  -- Trip Ticket ID
AS

BEGIN
    DECLARE @result NVARCHAR(4000) = '';
    DECLARE @word NVARCHAR(4000);
    DECLARE @pos INT;

    -- trim
    SET @string = LTRIM(RTRIM(@string)) + ' ';
    WHILE LEN(@string) > 0
    BEGIN
        SET @pos = CHARINDEX(' ', @string);
        SET @word = LEFT(@string, @pos - 1);

        IF LEN(@word) > 0
            SET @result = @result 
                        + UPPER(LEFT(@word, 1)) 
                        + LOWER(SUBSTRING(@word, 2, LEN(@word))) 
                        + ' ';

        SET @string = LTRIM(SUBSTRING(@string, @pos + 1, LEN(@string)));
    END

    RETURN RTRIM(@result);
END
